{{!-- Styling parameters: class, imageClass, contentClass, titleClass, descriptionClass, metaClass, footerClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Post Card
  Usage: Inside {{#foreach posts}} ... {{> "components/post-card"}} ... {{/foreach}}
--}}
<article class="gh-post-card{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}} group">
    {{#if feature_image}}
    <a href="{{url}}" class="gh-post-card-image">
        <img src="{{img_url feature_image size="m"}}" alt="{{#if feature_image_alt}}{{feature_image_alt}}{{else}}{{title}}{{/if}}" class="gh-post-card-img{{#if ghostcnStyles.imageClass}} {{ghostcnStyles.imageClass}}{{/if}}" loading="lazy" />
    </a>
    {{/if}}

    <div class="gh-post-card-content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
        <div>
            <div class="gh-post-card-meta{{#if ghostcnStyles.metaClass}} {{ghostcnStyles.metaClass}}{{/if}}">
                {{#if primary_tag}}
                <a href="{{primary_tag.url}}" class="gh-post-card-tag">{{primary_tag.name}}</a>
                <span class="gh-post-card-separator">&bull;</span>
                {{/if}}
                <span class="gh-post-card-reading-time">{{reading_time}}</span>
            </div>

            <h3 class="gh-post-card-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
                <a href="{{url}}">{{title}}</a>
            </h3>

            {{#if excerpt}}
            <p class="gh-post-card-excerpt{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{excerpt words="25"}}</p>
            {{/if}}
        </div>

        <div class="gh-post-card-footer{{#if ghostcnStyles.footerClass}} {{ghostcnStyles.footerClass}}{{/if}}">
            <div class="gh-post-card-author">
                {{#primary_author}}
                <span>{{name}}</span>
                {{/primary_author}}
            </div>
            <time datetime="{{date format="YYYY-MM-DD"}}">{{date format="D MMM YYYY"}}</time>
        </div>
    </div>
</article>
{{/with}}

/* ghostcn: Post Card Styles */
.gh-post-card {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 16px;
    line-height: 1.5;
    isolation: isolate;
    background-color: var(--card, #ffffff);
    color: var(--card-foreground, #09090b);
    border: 1px solid var(--border, #e4e4e7);
    border-radius: min(var(--radius, 0.5em), 1.5em);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
}

.gh-post-card *,
.gh-post-card *::before,
.gh-post-card *::after {
    box-sizing: border-box;
}

.gh-post-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.gh-post-card-image {
    aspect-ratio: 16 / 9;
    overflow: hidden;
    display: block;
    background-color: var(--muted, #f4f4f5);
}

.gh-post-card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.gh-post-card:hover .gh-post-card-image img {
    transform: scale(1.03);
}

.gh-post-card-content {
    padding: 1.25em;
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.gh-post-card-tag {
    color: var(--primary, var(--ghost-accent-color, #18181b));
    font-size: 0.75em;
    font-weight: 600;
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.gh-post-card-tag:hover {
    text-decoration: underline;
}

.gh-post-card-title {
    font-size: 1.25em;
    font-weight: 700;
    letter-spacing: -0.025em;
    margin: 0.5em 0;
    line-height: 1.35;
    color: var(--foreground, #09090b);
}

.gh-post-card-title a {
    color: inherit;
    text-decoration: none;
    transition: color 0.15s ease;
}

.gh-post-card-title:hover {
    color: var(--primary, var(--ghost-accent-color, #18181b));
}

.gh-post-card-excerpt {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
    color: var(--muted-foreground, #71717a);
    font-size: 0.875em;
    line-height: 1.5;
    margin-bottom: 1em;
}

.gh-post-card-footer {
    padding-top: 1em;
    border-top: 1px solid var(--border, #e4e4e7);
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 0.75em;
    color: var(--muted-foreground, #71717a);
}

.gh-post-card-meta { display: flex; align-items: center; gap: 0.5em; margin-bottom: 0.5em; font-size: 0.75em; font-weight: 600; }
.gh-post-card-reading-time { color: var(--muted-foreground); }
.gh-post-card-separator { color: color-mix(in srgb, var(--muted-foreground) 40%, transparent); }
.gh-post-card-author { display: flex; align-items: center; gap: 0.5em; font-weight: 500; }
